// SID: 2408078using Microsoft.EntityFrameworkCore;using GrapheneTrace.Areas.Identity.Data;using GrapheneTrace.Services.Interfaces;using GrapheneTrace.Models.Admin;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.Rendering;using GrapheneTrace.Data; using GrapheneTrace.Models.Database; using GrapheneTrace.Enums;using GrapheneTrace.Enums.Extensions;namespace GrapheneTrace.Services{    public class AdminService : IAdminService    {        private readonly ApplicationDbContext _context;        private readonly UserManager<ApplicationUser> _userManager;        public AdminService(UserManager<ApplicationUser> userManager, ApplicationDbContext context)        {            _userManager = userManager;            _context = context;        }        /// <summary>        /// Update user database entry with provided EditUserViewModel        /// </summary>        /// <param name="model"></param>         /// <returns></returns>        public async Task<bool> UpdateUser(EditUserViewModel model)        {            // Get user object            var user = await _userManager.FindByIdAsync(model.Id.ToString());            if (user == null)                return false;            // Populate model            user.Email = model.Email;            user.UserName = model.Email;            user.DateOfBirth = model.DateOfBirth;            user.Name = model.Name;            // Get users role            var userRoles = await _userManager.GetRolesAsync(user);            // Add new role            await _userManager.AddToRolesAsync(user, model.SelectedRoles.Except(userRoles));            // Remove old role            await _userManager.RemoveFromRolesAsync(user, userRoles.Except(model.SelectedRoles));            // If there changing their password            if (!string.IsNullOrEmpty(model.NewPassword))            {                // Check that passwords match                if (model.NewPassword != model.ConfirmPassword)                    return false;                // Validate password                foreach (var validator in _userManager.PasswordValidators)                {                    var result = await validator.ValidateAsync(_userManager, user, model.NewPassword);                    if (!result.Succeeded)                    {                        return false;                    }                }                                // Remove old password                await _userManager.RemovePasswordAsync(user);                // Add new password                await _userManager.AddPasswordAsync(user, model.NewPassword);            }            // Update user            var updateResult = await _userManager.UpdateAsync(user);            // Return result             return updateResult.Succeeded;        }                /// <summary>        /// Update the links between patients and clinicians        /// </summary>        /// <param name="idsToAdd"></param> The links to add        /// <param name="idsToRemove"></param> The links to remove        /// <param name="primaryUserId"></param> Who are we linking to?        /// <param name="primaryUserType"></param> What type of user are we linking to?        public async Task UpdatePatientClinicianLinks(List<int> idsToAdd, List<int> idsToRemove, int primaryUserId, UserType primaryUserType)        {            // If there are ids to add             if (idsToAdd.Count > 0)            {                // Create new patient clinician link objects depending on primary userType                var newLinks = idsToAdd.Select(id => primaryUserType switch                {                    UserType.Patient  => new PatientClinician { PatientId = primaryUserId, ClinicianId = id },                    UserType.Clinician => new PatientClinician { PatientId = id, ClinicianId = primaryUserId },                    _ =>  throw new ArgumentException("Can't link Admin too User")                });                // Add all the links                _context.PatientClinician.AddRange(newLinks);            }            // If there are ids to remove            if (idsToRemove.Count > 0)            {                // Find patient clinican links depending on the primary usertype                var linksToRemoveQuery = primaryUserType switch                {                    UserType.Patient => _context.PatientClinician.Where(pc =>                        pc.PatientId == primaryUserId && idsToRemove.Contains(pc.ClinicianId)),                    UserType.Clinician => _context.PatientClinician.Where(pc =>                        pc.ClinicianId == primaryUserId && idsToRemove.Contains(pc.PatientId)),                    _ => throw new ArgumentException("Can't link Admin too User")                };                                // Remove all the ids                _context.PatientClinician.RemoveRange(await linksToRemoveQuery.ToListAsync());            }            // Save the changes to db            await _context.SaveChangesAsync();        }        /// <summary>        /// Return all users linked to a specific user        /// </summary>        /// <param name="id"></param> The id of the user we want to find the links of        /// <param name="type"></param> The type of that user        /// <returns></returns>        public async Task<List<int>> GetAlreadyLinkedUsers(int id, UserType type)        {            // Build query depending on user type            return type switch            {                UserType.Clinician => await _context.PatientClinician                    .Where(pc => pc.ClinicianId == id)                     .Select(pc => pc.PatientId)                    .ToListAsync(),                UserType.Patient => await _context.PatientClinician                    .Where(pc => pc.PatientId == id)                    .Select(pc => pc.ClinicianId)                    .ToListAsync(),                UserType.Admin => throw new ArgumentException("Admin cannot be linked"),                _ => throw new ArgumentException("User Type cannot be linked")            };        }        /// <summary>        /// Get the available or already assigned links of a certain user        /// </summary>        /// <param name="userType"></param> The type of User        /// <param name="userId"></param> The User's id        /// <param name="filterMode"></param> The filter: Assigned or Available        /// <returns></returns>        public async Task<IList<SelectListItem>> GetLinkSelectionList(UserType userType, int userId, LinkFilter filterMode)        {            // Get all users in the role userType            var allUsers = await _userManager.GetUsersInRoleAsync(userType.ToString());            // Get id's already linked to user            var linkedIdsSet = new HashSet<int>(await GetAlreadyLinkedUsers(userId, userType.Opposite()));            // Filter the ids            var filteredUsers = filterMode switch            {                LinkFilter.Assigned  => allUsers.Where(u => linkedIdsSet.Contains(u.Id)),                 LinkFilter.Available => allUsers.Where(u => !linkedIdsSet.Contains(u.Id)),                _                    => []            };            // Return as select list items            return filteredUsers                .Select(u => new SelectListItem                {                    Text = $"{u.Name} ({u.Email})",                    Value = u.Id.ToString()                })                .ToList();        }                /// <summary>        /// Get all the users to be displayed on the admin dashboard        /// </summary>        /// <param name="searchString"></param> The string used to search for users        /// <returns></returns>        public async Task<List<UserViewModel>> GetAdminDashboardUsersAsync(string searchString)        {            var query = _context.Users.AsNoTracking();                        // If there is a search string            if (!string.IsNullOrWhiteSpace(searchString))            {                // If search string is a number parese it to an int                var isIdSearch = int.TryParse(searchString, out var searchId);                // Build query                query = query.Where(u =>                    u.Email != null && ((isIdSearch && u.Id == searchId) ||                                         u.Email.Contains(searchString) ||                                        u.Name.Contains(searchString) ||                                        _context.UserRoles                                            .Where(ur => ur.UserId == u.Id)                                            .Join(_context.Roles, ur => ur.RoleId, r => r.Id, (ur, r) => r.Name)                                            .Any(rName => rName != null && rName.Contains(searchString)))                );            }                        // Build UserViewModel            var users = await query.Select(u => new UserViewModel                {                    Id = u.Id,                    Email = u.Email ?? "",                    Name = u.Name,                    DateOfBirth = u.DateOfBirth,                                        PatientLinkCount = _context.PatientClinician.Count(pc => pc.PatientId == u.Id),                    ClinicianLinkCount = _context.PatientClinician.Count(pc => pc.ClinicianId == u.Id),                                        Roles = _context.UserRoles                        .Where(ur => ur.UserId == u.Id)                        .Join(_context.Roles, ur => ur.RoleId, r => r.Id, (ur, r) => r.Name)                        .ToList()                })                .ToListAsync();            // Return all users            return users;        }        /// <summary>        /// Create a new user        /// </summary>        /// <param name="model"></param> CreateUserViewModel containing details of new user        /// <returns></returns>        public async Task<IdentityResult> CreateUser(CreateUserViewModel model)        {            // Populate ApplicationUser object            var user = new ApplicationUser            {                UserName = model.Email,                Email = model.Email,                Name = model.Name,                DateOfBirth = model.DateOfBirth,                EmailConfirmed = true            };                        // Create the user            var createResult = await _userManager.CreateAsync(user, model.Password);            // Return result if failed            if (!createResult.Succeeded)            {                return createResult;             }                        // Assign the user role            var roleResult = await _userManager.AddToRoleAsync(user, model.SelectedRole);            // Return result if succeeded            if (roleResult.Succeeded) return IdentityResult.Success;                        // If failed, delete user            await _userManager.DeleteAsync(user);                        // Return result            return roleResult;        }                /// <summary>        /// Delete a user        /// </summary>        /// <param name="targetUserId"></param> The user to be deleted        /// <param name="currentId"></param> The id of the user doing the deleting         /// <returns></returns>        public async Task<DeleteUserStatus> DeleteUserAsync(int targetUserId, int currentId)        {            // Make sure you can't delete yourself            if (targetUserId == currentId)            {                return DeleteUserStatus.CannotDeleteSelf;            }                        // Get the user object            var user = await _userManager.FindByIdAsync(targetUserId.ToString());                        // Check user exists            if (user == null)            {                return DeleteUserStatus.UserNotFound;            }                        // Delete the user            var result = await _userManager.DeleteAsync(user);            // Return result            return !result.Succeeded ? DeleteUserStatus.DatabaseError : DeleteUserStatus.Success;        }    }}